import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();

        int[] parent = new int[p];
        int[] size = new int[p];
        for (int i = 0; i < p; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        // find root with path compression
        java.util.function.Function<Integer, Integer> findRoot = new java.util.function.Function<Integer, Integer>() {
            public Integer apply(Integer u) {
                while (parent[u] != u) {
                    parent[u] = parent[parent[u]];
                    u = parent[u];
                }
                return u;
            }
        };

        // union sets
        java.util.function.BiConsumer<Integer, Integer> unionSets = (u, v) -> {
            u = findRoot.apply(u);
            v = findRoot.apply(v);
            if (u != v) {
                size[u] += size[v];
                parent[v] = u;
            }
        };

        // power_mod function
        java.util.function.BiFunction<Long, Long, Long> powerMod = (base, exp) -> {
            long res = 1;
            long b = base;
            long e = exp;
            while (e > 0) {
                if ((e & 1) == 1) {
                    res = (res * b) % 1000000007;
                }
                b = (b * b) % 1000000007;
                e >>= 1;
            }
            return res;
        };

        // check_power function
        java.util.function.BiFunction<Long, Long, Long> checkPower = (a, b) -> {
            long res = 1;
            long base = a;
            long exponent = b;
            while (exponent > 0) {
                if ((exponent & 1) == 1) {
                    res = (res * base) % p;
                }
                base = (base * base) % p;
                exponent >>= 1;
            }
            return res == 1 ? p : 1;
        };

        if (k == 0) {
            System.out.println(powerMod.apply((long) p, (long) p - 1));
            sc.close();
            return;
        }

        for (int i = 0; i < p; i++) {
            parent[i] = i;
        }

        for (int i = 0; i < p; i++) {
            long v = ((long) k * i) % p;
            unionSets.accept(i, (int) v);
        }

        long answer = 1;
        for (int i = 0; i < p; i++) {
            if (findRoot.apply(i) == i) {
                answer = (answer * checkPower.apply((long) k, (long) size[i])) % 1000000007;
            }
        }

        System.out.println(answer);
        sc.close();
    }
}
